public int myAtoi(String s) {
    // states: 0=START, 1=SIGNED, 2=IN_NUMBER, 3=END
    // cols:   0=space, 1=sign, 2=digit, 3=other
    int[][] table = {
        {0, 1, 2, 3},
        {3, 3, 2, 3},
        {3, 3, 2, 3},
        {3, 3, 3, 3}
    };
    int state = 0, sign = 1;
    long result = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        state = table[state][col(c)];
        if (state == 3) break;             // END
        if (state == 1) {                  // SIGNED
            sign = (c == '-') ? -1 : 1;
        } else if (state == 2) {           // IN_NUMBER
            result = result * 10 + (c - '0');
            if (sign == 1 && result > Integer.MAX_VALUE) return Integer.MAX_VALUE;
            if (sign == -1 && -result < Integer.MIN_VALUE) return Integer.MIN_VALUE;
        }
    }
    return (int) (sign * result);
}

private int col(char c) {
    if (c == ' ') return 0;
    if (c == '+' || c == '-') return 1;
    if (Character.isDigit(c)) return 2;
    return 3;
}

code.python:
def myAtoi(self, s: str) -> int:
    INT_MAX, INT_MIN = 2**31 - 1, -2**31
    # states: START, SIGNED, IN_NUMBER, END ; cols: space, sign, digit, other
    table = {
        "START":     ["START", "SIGNED", "IN_NUMBER", "END"],
        "SIGNED":    ["END",   "END",    "IN_NUMBER", "END"],
        "IN_NUMBER": ["END",   "END",    "IN_NUMBER", "END"],
        "END":       ["END",   "END",    "END",       "END"],
    }

    def col(ch: str) -> int:
        if ch == " ":
            return 0
        if ch in ("+", "-"):
            return 1
        if ch.isdigit():
            return 2
        return 3

    state, sign, result = "START", 1, 0
    for ch in s:
        state = table[state][col(ch)]
        if state == "END":
            break
        if state == "SIGNED":
            sign = -1 if ch == "-" else 1
        elif state == "IN_NUMBER":
            result = result * 10 + int(ch)
            if sign == 1 and result > INT_MAX:
                return INT_MAX
            if sign == -1 and -result < INT_MIN:
                return INT_MIN
    return sign * result

